use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

/// How many times to offer the notification before giving up.
const NOTIFY_ATTEMPTS: u32 = 3;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the wall-clock time once.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: one permitted fetch. A transport failure comes back as a
        // value, so a dead feed counts as zero characters instead of failing
        // the heartbeat. A URL outside the allowlist traps at the boundary,
        // and the node does not try to work around that.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: send the heartbeat.
        let message = format!(
            "heartbeat: t={} feed={} fetched={} chars",
            seconds, feed_url, fetched
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // Contract: `ensures notified == true`. If the channel never accepted
        // the notification, the node cannot honestly produce a conforming
        // output, so it traps instead of returning a report that breaks the
        // contract or reports a delivery that did not happen.
        if !notified {
            panic!("heartbeat: notifier refused the message");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
